// Checks whether a PDF already has an embedded, selectable text layer
// (a "digital" PDF generated by lab software) vs. one that's actually a
// scan/photo with no real text underneath. When a text layer exists, no
// OCR engine is needed at all — a free, instant, zero-error text pull
// replaces the entire OCR step (PaddleOCR here, ~30 s/page on this CPU —
// skipping it whenever possible matters a lot more here than in the other
// demos). Started as a copy of ../deepseek-ocr/triage.js /
// ../paddleocr/triage.js / ../azure-llm/pdfText.js; this copy additionally
// rejects empty and garbage text layers (textQuality below) — the others
// don't have that yet.
//
// Known trade-off, kept visible rather than hidden: this plain extraction
// does NOT reconstruct table structure — rows/columns can come out jumbled
// — so the local LLM has messier input to work with than it would from a
// vision model actually reading the page. That's the real cost/accuracy
// trade this branch makes, not a free lunch.

const { PDFParse } = require('pdf-parse');

const MIN_CHARS_FOR_DIGITAL = 200;

// A text layer only counts as "digital" if it is real, readable text.
// Two general failure modes seen on scanned PDFs (PROGRESS.md "First batch
// evaluation"):
//  A. near-empty: only pdf-parse's own "-- N of M --" page markers →
//     measured as letters per page, markers excluded.
//  B. a garbage OCR layer embedded by the scanner ("Palr,:nl Nanre") →
//     measured as the share of word tokens that are clean alphabetic words.
// PROVISIONAL threshold: chosen on the first 9-file batch, where clean
// reports scored 0.87-0.93 and garbled layers 0.73-0.79 — re-check it on
// larger batches (batch-eval.js) before trusting it; don't tune it to one file.
const MIN_LETTERS_PER_PAGE = 50;
const MIN_CLEAN_WORD_RATIO = 0.83;
const PAGE_MARKER_RE = /--\s*\d+\s+of\s+\d+\s*--/g;

function textQuality(text) {
  const pages = (text.match(PAGE_MARKER_RE) || []).length || 1;
  const body = text.replace(PAGE_MARKER_RE, '');
  const letters = (body.match(/[a-z]/gi) || []).length;
  const words = body.split(/\s+/).filter((w) => /[a-z]/i.test(w));
  const clean = words.filter((w) => /^[(\[]?[A-Za-z]+[)\],.:;]?$/.test(w)).length;
  return {
    pages,
    lettersPerPage: Math.round(letters / pages),
    cleanWordRatio: words.length ? +(clean / words.length).toFixed(2) : 0,
  };
}

async function extractDigitalText(fileBuffer) {
  const parser = new PDFParse({ data: fileBuffer });
  try {
    const result = await parser.getText();
    return result.text || '';
  } finally {
    await parser.destroy();
  }
}

// Returns { isDigital, text, reason } — text is only populated when digital.
async function triage(fileBuffer, mimeType) {
  if (mimeType !== 'application/pdf') {
    return { isDigital: false, text: '', reason: 'Not a PDF (image file) — always needs OCR.' };
  }

  let text = '';
  try {
    text = await extractDigitalText(fileBuffer);
  } catch (err) {
    return { isDigital: false, text: '', reason: `Could not read a text layer (${err.message}) — falling back to OCR.` };
  }

  const meaningfulChars = text.replace(PAGE_MARKER_RE, '').replace(/\s+/g, '').length;
  const quality = textQuality(text);
  if (meaningfulChars < MIN_CHARS_FOR_DIGITAL || quality.lettersPerPage < MIN_LETTERS_PER_PAGE) {
    return { isDigital: false, text: '', quality, reason: `Text layer is empty or near-empty (${meaningfulChars} characters, ${quality.lettersPerPage} letters/page) — this is a scan, needs OCR.` };
  }
  if (quality.cleanWordRatio < MIN_CLEAN_WORD_RATIO) {
    return { isDigital: false, text: '', quality, reason: `Text layer looks like a low-quality embedded OCR layer (clean-word ratio ${quality.cleanWordRatio} < ${MIN_CLEAN_WORD_RATIO}) — treating as a scan, needs OCR.` };
  }
  return { isDigital: true, text, quality, reason: `Found a real text layer (${meaningfulChars} characters, clean-word ratio ${quality.cleanWordRatio}) — no OCR needed.` };
}

// Per-page version of the same checks, for mixed PDFs (scanned pages +
// digital pages in one file). A page's text layer is usable when it has
// enough letters and — if it has enough words to judge — a clean-word
// ratio above the same provisional threshold.
//
// Per page, word quality is judged only on word-like tokens: numbers, units
// and ranges ("milli./cu.mm", "11.5-17.5") aren't words either way, and
// counting them made unit-heavy lab pages look garbled. Only clear garbage
// is rejected here (< 0.80 — clean pages measured 0.86-0.99, garbled layers
// 0.65-0.85 on the first batch); pageReader.js adds the stronger check —
// a lab-looking page whose text yields no results goes to OCR.
const MIN_PAGE_LETTERS = 30;
const MIN_WORDS_TO_JUDGE = 25;
const MIN_PAGE_WORD_RATIO = 0.80;

function wordRatio(text) {
  const words = String(text || '').split(/\s+/).filter((w) => /[a-z]/i.test(w) && !/[\d/]/.test(w));
  const clean = words.filter((w) => /^[(\["']?[A-Za-z]+(['’][a-z]+)?[)\],.:;"'-]?$/.test(w)).length;
  return { words: words.length, ratio: words.length ? +(clean / words.length).toFixed(2) : 0 };
}

function pageTextUsable(text) {
  const letters = (String(text || '').match(/[a-z]/gi) || []).length;
  const w = wordRatio(text);
  const quality = { letters, words: w.words, wordRatio: w.ratio };
  if (letters < MIN_PAGE_LETTERS) return { usable: false, reason: 'no text', quality };
  if (w.words >= MIN_WORDS_TO_JUDGE && w.ratio < MIN_PAGE_WORD_RATIO) return { usable: false, reason: `garbled text layer (word ratio ${w.ratio})`, quality };
  return { usable: true, reason: 'text layer', quality };
}

// → [{ page, text, usable, reason, quality }] for every page of a PDF
async function triagePages(fileBuffer) {
  const parser = new PDFParse({ data: fileBuffer });
  let result;
  try {
    result = await parser.getText();
  } catch {
    result = { pages: [] };
  } finally {
    await parser.destroy();
  }
  return (result.pages || []).map((p) => ({ page: p.num, text: p.text || '', ...pageTextUsable(p.text) }));
}

module.exports = { triage, triagePages, pageTextUsable, textQuality, MIN_CLEAN_WORD_RATIO };
